        Map<String,Object> receipt=obj("taskId",group.get("taskId"),"phase","GROUP_DISCOVERY","taskIds",group.get("taskIds"),"sourceIds",group.get("sourceIds"),"sources",group.get("sources"),"rootKeys",group.get("rootKeys"),"basisKinds",group.get("basisKinds"),"taskReceipts",new ArrayList<>(),"issues",new ArrayList<>(),"modelCalls",0);
