    private static JsonNode repairRequirementQuotes(JsonNode previous,JsonNode next,List<Object> normalizations,List<Object> repairs){
        Map<String,JsonNode> proposed=new LinkedHashMap<>();Set<String> duplicates=new HashSet<>();
        for(JsonNode draft:Arrays.asList(previous,next)){Set<String> seen=new HashSet<>();for(JsonNode row:draft.path("requirements")){String id=row.path("id").asText();if(!seen.add(id))duplicates.add(id);if(draft==next)proposed.put(id,row);}}
        ObjectNode result=null;
        for(int index=0;index<previous.path("requirements").size();index++){
            JsonNode prior=previous.path("requirements").get(index),candidate=proposed.get(prior.path("id").asText());if(candidate==null||duplicates.contains(prior.path("id").asText()))continue;
            boolean same=true;for(String field:Arrays.asList("id","sourceTaskId","kind","nodeIds"))same&=prior.has(field)&&prior.path(field).equals(candidate.path(field));
            if(!same||!candidate.path("sourceQuote").isTextual()||candidate.path("sourceQuote").asText().trim().isEmpty()||candidate.hasNonNull("sourceObservationId")&&!candidate.path("sourceObservationId").isTextual())continue;
            boolean allowed=false;for(Object raw:repairs){Map<String,Object> repair=map(raw);allowed|="requirement_quote_not_in_authorized_evidence".equals(repair.get("reason"))&&prior.path("sourceTaskId").asText().equals(repair.get("sourceTaskId"))&&list(repair.get("requirementIds")).contains(prior.path("id").asText());}if(!allowed)continue;
            ObjectNode revised=(ObjectNode)prior.deepCopy();revised.set("sourceQuote",candidate.path("sourceQuote").deepCopy());if(candidate.hasNonNull("sourceObservationId"))revised.set("sourceObservationId",candidate.path("sourceObservationId").deepCopy());else revised.remove("sourceObservationId");
            if(revised.equals(prior))continue;if(result==null)result=(ObjectNode)previous.deepCopy();((ArrayNode)result.path("requirements")).set(index,revised);
            normalizations.add(obj("kind","requirement_quote_targeted_repair","requirementId",prior.path("id").asText(),"sourceTaskId",prior.path("sourceTaskId").asText(),"previousRequirementSha256",DraftAdoption.hash(JsonUtils.write(prior)),"replacementRequirementSha256",DraftAdoption.hash(JsonUtils.write(revised)),"retained","original_responses"));
        }
        return result==null?previous:result;
    }
    private static JsonNode repairOutcomes(JsonNode previous,JsonNode merged,List<Object> repairs,Map<String,Object> checked){if(!previous.has("taskOutcomes")&&!merged.has("taskOutcomes"))return merged;Set<String> targets=new HashSet<>(),resolved=new HashSet<>();for(Object raw:repairs)targets.add(text(map(raw).get("sourceTaskId")));if(checked!=null)for(Object raw:list(checked.get("taskReceipts"))){Map<String,Object> child=map(raw),coverage=map(child.get("scopeCoverage"));if(!coverage.isEmpty()&&list(coverage.get("missingScopeIds")).isEmpty())resolved.add(text(child.get("taskId")));}Map<String,JsonNode> old=new LinkedHashMap<>();for(JsonNode row:previous.path("taskOutcomes"))old.put(row.path("sourceTaskId").asText(),row);Map<String,JsonNode> retained=new LinkedHashMap<>(old);for(JsonNode row:merged.path("taskOutcomes")){String id=row.path("sourceTaskId").asText();if(!targets.contains(id))continue;JsonNode prior=old.get(id);if(checked!=null&&prior!=null&&"unresolved".equals(prior.path("status").asText())&&!resolved.contains(id))continue;retained.put(id,row);}ArrayNode outcomes=JsonUtils.mapper().createArrayNode();retained.values().forEach(outcomes::add);if(outcomes.equals(merged.path("taskOutcomes")))return merged;ObjectNode result=JsonUtils.mapper().createObjectNode();merged.fields().forEachRemaining(field->result.set(field.getKey(),field.getValue()));result.set("taskOutcomes",outcomes);return result;}
    private static ArrayNode mergeScopeRules(JsonNode previous,JsonNode next,List<Object> issues,List<Object> normalizations,List<Object> repairs){
        Map<String,Integer> previousCounts=scopeRuleCounts(previous),nextCounts=scopeRuleCounts(next);Map<String,JsonNode> rows=new LinkedHashMap<>();
        for(JsonNode draft:Arrays.asList(previous,next)){
            if(draft.has("scopeRules")&&!draft.path("scopeRules").isArray()){issues.add(obj("reason","scope_rules_array_required"));continue;}
            Set<String> ownIds=new HashSet<>();for(JsonNode rule:draft.path("scopeRules")){
                String id=rule.path("id").asText();JsonNode prior=rows.putIfAbsent(id,rule);boolean duplicate=!ownIds.add(id),changed=prior!=null&&!prior.equals(rule);
                Map<String,Object> repair=changed&&draft==next&&!duplicate&&previousCounts.getOrDefault(id,0)==1&&nextCounts.getOrDefault(id,0)==1?scopeRuleRepair(prior,rule,repairs):Collections.emptyMap();
                if(!repair.isEmpty()){
                    rows.put(id,rule);String reason=text(repair.get("reason"));normalizations.add(obj("kind","scope_rule_targeted_repair","scopeRuleId",id,"sourceTaskId",rule.path("sourceTaskId").asText(),"scopeId",rule.path("scopeId").asText(),"previousRuleSha256",DraftAdoption.hash(JsonUtils.write(prior)),"replacementRuleSha256",DraftAdoption.hash(JsonUtils.write(rule)),"repairReason",reason.isEmpty()?"explicit_scope_rule_repair":reason));
                }else if(id.isEmpty()||duplicate||changed)issues.add(obj("reason","scope_rule_identity_conflict","scopeRuleId",id,"retained","first_rule_and_original_responses"));
            }
        }ArrayNode result=JsonUtils.mapper().createArrayNode();rows.values().forEach(rule->result.add(rule.deepCopy()));return result;
    }
    private static Map<String,Integer> scopeRuleCounts(JsonNode draft){Map<String,Integer> counts=new HashMap<>();if(draft.path("scopeRules").isArray())for(JsonNode rule:draft.path("scopeRules")){String id=rule.path("id").asText();counts.put(id,counts.getOrDefault(id,0)+1);}return counts;}
    private static Map<String,Object> scopeRuleRepair(JsonNode prior,JsonNode next,List<Object> repairs){
        // Raw scope rules have no review state; reject enriched or authority-bearing records instead of treating them as pending.
        Set<String> fields=new HashSet<>(Arrays.asList("id","sourceTaskId","scopeId","when","action","replacementEn","valueSourceId","refinedQuote"));
        for(JsonNode rule:Arrays.asList(prior,next)){if(!rule.isObject())return Collections.emptyMap();Iterator<String> names=rule.fieldNames();while(names.hasNext())if(!fields.contains(names.next()))return Collections.emptyMap();}
        for(String key:Arrays.asList("id","sourceTaskId","scopeId"))if(!prior.path(key).isTextual()||prior.path(key).asText().isEmpty()||!prior.path(key).equals(next.path(key)))return Collections.emptyMap();
        for(Object raw:repairs){Map<String,Object> repair=map(raw);if((prior.path("sourceTaskId").asText().equals(repair.get("sourceTaskId"))||list(repair.get("sourceTaskIds")).contains(prior.path("sourceTaskId").asText()))&&list(repair.get("ruleIds")).contains(prior.path("id").asText())&&list(repair.get("scopeIds")).contains(prior.path("scopeId").asText()))return repair;}
        return Collections.emptyMap();
    }
