    private static void retainScopeCoverage(Plan plan,Map<String,Map<String,Object>> children,List<Map<String,Object>> nodes,Map<String,List<ScopeDuty>> duties) {
        Map<String,Map<String,Object>> sourceTasks=new HashMap<>();for(Map<String,Object> task:plan.tasks)if(children.containsKey(text(task.get("taskId"))))sourceTasks.put(text(task.get("taskId")),task);Map<String,Boolean> inheritance=new HashMap<>();
        Map<String,String> directives=new HashMap<>();for(List<ScopeDuty> rows:duties.values())for(ScopeDuty duty:rows)directives.put(duty.task,duty.directive);List<ScopeProof> proofs=new ArrayList<>();Set<String> retainedScopes=new HashSet<>();
        for(Map<String,Object> node:nodes)for(Object raw:list(node.get("editTargets"))){Map<String,Object> target=map(raw);String owner=text(target.get("sourceTaskId"));if(owner.isEmpty())owner=text(node.get("sourceTaskId"));String key=scopeKey(plan.readings.get(text(target.get("docId"))),text(target.get("sourceScopeId")));if(!key.isEmpty()&&Boolean.TRUE.equals(target.get("scopeComplete"))&&!Boolean.TRUE.equals(target.get("needsRebind"))&&!target.containsKey("scopeQuoteIssue")&&!target.containsKey("refinementIssue")&&!"check".equals(target.get("action"))&&!map(target.get("native")).isEmpty())proofs.add(new ScopeProof(owner,key,text(node.get("id"))));else if(!key.isEmpty())retainedScopes.add(owner+"|"+key);}
        for(Map<String,Object> child:children.values())for(Object raw:list(child.get("requirements"))){Map<String,Object> requirement=map(raw),evidence=map(requirement.get("sourceQuoteEvidence"));if("verification".equals(requirement.get("kind"))&&"scope".equals(evidence.get("kind"))){String key=scopeKey(plan.readings.get(text(child.get("sourceId"))),text(evidence.get("sourceObservationId")));if(!key.isEmpty())proofs.add(new ScopeProof(text(child.get("taskId")),key,""));}}
        // Exact duplicate duties may share an existing pending target, never its coverage or edit authority.
        Set<String> retainedDirectives=new HashSet<>();for(List<ScopeDuty> rows:duties.values())for(ScopeDuty duty:rows)if(!duty.key.isEmpty()&&!duty.directive.isEmpty()&&retainedScopes.contains(duty.task+"|"+duty.key))retainedDirectives.add(duty.key+"\n"+duty.directive);
        for(Map.Entry<String,Map<String,Object>> entry:children.entrySet()){List<ScopeDuty> expected=duties.getOrDefault(entry.getKey(),Collections.emptyList());if(expected.isEmpty())continue;List<Object> all=new ArrayList<>(),missing=new ArrayList<>(),unrepresented=new ArrayList<>();Set<String> shared=new LinkedHashSet<>();
            for(ScopeDuty duty:expected){all.add(duty.id);boolean covered=false;for(ScopeProof proof:proofs)if(!duty.key.isEmpty()&&!retainedScopes.contains(duty.task+"|"+duty.key)&&!retainedScopes.contains(proof.owner+"|"+proof.key)&&duty.key.equals(proof.key)){boolean own=entry.getKey().equals(proof.owner);boolean duplicate=!duty.directive.isEmpty()&&duty.directive.equals(directives.get(proof.owner));boolean inherited=!own&&!duplicate&&inheritance.computeIfAbsent(proof.owner+"|"+entry.getKey()+"|"+duty.id,key->DraftScopeDutyInheritance.exactMarkerChild(plan.readings.get(duty.source),sourceTasks.get(proof.owner),sourceTasks.get(entry.getKey()),duty.id));if(own||duplicate||inherited){covered=true;if(!entry.getKey().equals(proof.owner))shared.add(proof.owner);break;}}if(!covered){missing.add(duty.id);if(!retainedScopes.contains(duty.task+"|"+duty.key)&&!retainedDirectives.contains(duty.key+"\n"+duty.directive))unrepresented.add(duty.id);}}
            Map<String,Object> child=entry.getValue();child.put("scopeCoverage",obj("status",missing.isEmpty()?shared.isEmpty()?"covered":"shared_exact":"unresolved","scopeIds",all,"missingScopeIds",missing,"unrepresentedScopeIds",unrepresented,"sharedFromTaskIds",new ArrayList<>(shared)));if(!missing.isEmpty())list(child.get("issues")).add(obj("reason","group_scope_disposition_missing","scopeIds",missing));
        }
    }
