                for(String identity:Arrays.asList("analysisRevision","analysisInputSha256","analysisSha256"))if(!reading.path(identity).asText().trim().isEmpty())retained.put(identity,reading.path(identity).asText());
                list(receipt.get("requirements")).add(retained);
