        for(int offset=0;offset<newIds.size();offset+=24){List<String> focus=new ArrayList<>(newIds.subList(offset,Math.min(newIds.size(),offset+24)));String id="link-"+DraftAdoption.hash(JsonUtils.write(ids)+"|"+JsonUtils.write(focus)).substring(0,24);tasks.add(obj("taskId",id,"phase","LINKING_GRAPH","nodeIds",focus,"catalogNodeIds",ids));}
