    static List<Object> fixedCatalogFocus(Plan plan,List<?> focus,Map<String,Map<String,Object>> nodes) {
        List<Object> eligible=new ArrayList<>();for(Object raw:focus){Map<String,Object> node=nodes.get(text(raw));if(node==null||plan.knownRoots.has(text(raw)))continue;List<?> documents=list(node.get("docIds"));if(documents.isEmpty())continue;boolean usable=true;
            for(Object document:documents){JsonNode source=plan.readings.get(text(document));if(source==null||!"bound".equals(source.path("evidenceStatus").asText())||source.path("fileKey").asText().isEmpty()||source.path("format").asText().isEmpty()){usable=false;break;}}
            if(usable)eligible.add(raw);
        }return eligible;
    }
    private static List<Object> relationWindow(List<Object> catalog,List<?> focus,List<?> queries,int limit) {
        Set<String> terms=new LinkedHashSet<>();for(Object query:queries)for(String token:text(query).toLowerCase(Locale.ROOT).split("[^\\p{L}\\p{N}]+"))if(token.length()>=4)terms.add(token);
        List<Map<String,Object>> ranked=new ArrayList<>();for(Object raw:catalog){Map<String,Object> row=map(raw);if(focus.contains(row.get("id")))continue;String contents=(text(row.get("nameEn"))+" "+text(row.get("nameZh"))+" "+text(row.get("sourceQuote"))).toLowerCase(Locale.ROOT);int score=0;for(String token:terms)if(contents.contains(token))score++;Map<String,Object> candidate=new LinkedHashMap<>(row);candidate.put("_score",score);ranked.add(candidate);}
        ranked.sort((a,b)->Integer.compare((Integer)b.get("_score"),(Integer)a.get("_score")));List<Object> result=new ArrayList<>();for(Map<String,Object> row:ranked){row.remove("_score");result.add(row);if(result.size()>=limit)break;}return result;
    }
